function SubChildItem({ text, onItemClick, activeTab }) {
  const isActive = text === activeTab;
  return (
    <div 
      className={`flex items-center gap-2 pl-9 pr-4 py-1.5 text-[12px] cursor-pointer transition-colors ${
        isActive ? 'bg-[#ff6b6b]/30 text-white font-bold border-l-2 border-[#ff6b6b]' : 'text-gray-300 hover:text-white hover:bg-white/5'
      }`}
      onClick={() => onItemClick(text)}
    >
      <span className={`text-[8px] ${isActive ? 'text-[#ff6b6b]' : 'text-gray-400'}`}>●</span>
      <span className="truncate">{text}</span>
    </div>
  );
}

function ChildItem({ text, children = [], isOpen, onToggle, onItemClick, activeTab }) {
  const hasChildren = children && children.length > 0;
  const isActive = text === activeTab || (hasChildren && children.some(sub => sub.text === activeTab));

  return (
    <div>
      <div
        className={`flex items-center justify-between px-4 py-2 cursor-pointer transition-colors group ${
          isActive ? 'text-white font-bold bg-white/10' : 'text-gray-300 hover:bg-white/5 hover:text-white'
        }`}
        onClick={() => hasChildren ? onToggle() : onItemClick(text)}
      >
        <div className="flex items-center gap-2.5 min-w-0">
          <span className="text-[8px] text-gray-300 shrink-0">●</span>
          <span className={`text-[12.5px] truncate ${isActive ? 'text-white font-bold' : isOpen ? 'text-white font-semibold' : 'text-gray-300 group-hover:text-white'}`}>{text}</span>
        </div>
        {hasChildren && (
          <span className={`text-[11px] text-gray-300 transition-transform duration-200 ${isOpen ? 'rotate-90 text-white font-bold' : ''}`}>
            &gt;
          </span>
        )}
      </div>
      {hasChildren && isOpen && (
        <div className="bg-[#1c242c]/90 py-1">
          {children.map((sub, i) => (
            <SubChildItem key={i} text={sub.text} onItemClick={onItemClick} activeTab={activeTab} />
          ))}
        </div>
      )}
    </div>
  );
}

function SidebarItem({ icon, text, active = false, children = [], isOpen, isExpanded, onToggle, onItemClick, activeTab }) {
  const [openChildIndex, setOpenChildIndex] = useState(null);
  const hasChildren = children && children.length > 0;

  if (!isExpanded) {
    return (
      <div
        className={`w-10 h-10 flex items-center justify-center cursor-pointer transition-colors ${
          active 
            ? 'text-white bg-[#ff6b6b] rounded-lg shadow' 
            : 'text-gray-400 hover:text-white hover:bg-gray-700/60 rounded-lg'
        }`}
        title={text}
        onClick={onToggle}
      >
        <span className="text-lg">{icon}</span>
      </div>
    );
  }

  return (
    <div>
      <div
        className={`flex items-center justify-between px-4 py-2.5 cursor-pointer transition-colors ${
          active 
            ? 'bg-[#ff6b6b] text-white font-bold shadow-xs' 
            : 'text-gray-300 hover:bg-gray-700/40 hover:text-white font-medium'
        }`}
        onClick={() => hasChildren ? onToggle() : onItemClick(text)}
      >
        <div className="flex items-center gap-3 min-w-0">
          <span className={`text-base shrink-0 ${active ? 'text-white' : 'text-gray-400'}`}>{icon}</span>
          <span className="text-[13px] truncate">{text}</span>
        </div>
        {hasChildren && (
          <span className={`text-[12px] font-bold transition-transform duration-200 ${active ? 'text-white' : 'text-gray-400'} ${isOpen ? 'rotate-90' : ''}`}>
            {isOpen ? '∨' : '>'}
          </span>
        )}
      </div>

      {/* Level-2 children */}
      {hasChildren && isOpen && (
        <div className="bg-[#212932] py-1 border-l-2 border-[#ff6b6b]/40 ml-2">
          {children.map((child, i) => (
            <ChildItem 
              key={i} 
              text={child.text} 
              children={child.children || []} 
              isOpen={openChildIndex === i}
              onToggle={() => setOpenChildIndex(openChildIndex === i ? null : i)}
              onItemClick={onItemClick}
              activeTab={activeTab}
            />
          ))}
        </div>
      )}
    </div>
  );
}


