  const getStudentsForClass = (clsName) => {
    if (studentImageDatabase[clsName]) {
      return studentImageDatabase[clsName];
    }
    const firstNames = ['AARAV', 'ANANYA', 'ADITYA', 'AVANI', 'AYUSH', 'DIYA', 'ISHAAN', 'KAVYA', 'MANAV', 'MYRA', 'PRANAV', 'RIYA', 'ROHIT', 'SAANVI', 'SHIVAM', 'SNEHA', 'TANVI', 'UTKARSH', 'VAISHNAVI', 'YASH'];
    const lastNames = ['GUPTA', 'YADAV', 'SINGH', 'PANDEY', 'TIWARI', 'MISHRA', 'JAISWAL', 'CHAUBEY', 'VERMA', 'RAI', 'KUSHWAHA', 'PATEL', 'SHARMA', 'BHARATI', 'GOND'];
    const fatherFirstNames = ['RAMESH', 'SURESH', 'MAHESH', 'DINESH', 'RAJESH', 'MANOJ', 'SANJAY', 'VIJAY', 'SUNIL', 'ANIL', 'PRAKASH', 'ASHOK', 'MUKESH', 'ALOK', 'VINOD'];

    const classSeed = clsName ? clsName.split('').reduce((acc, c) => acc + c.charCodeAt(0), 0) : 10;
    const count = 20 + (classSeed % 12);
    const result = [];
    for (let i = 1; i <= count; i++) {
      const fn = firstNames[(i + classSeed) % firstNames.length];
      const ln = lastNames[(i * 3 + classSeed) % lastNames.length];
      const ffn = fatherFirstNames[(i * 2 + classSeed) % fatherFirstNames.length];
      const adm = (2000 + ((classSeed * 17 + i * 23) % 4000)).toString();
      result.push({
        sr: i,
        adm: adm,
        name: `${fn} ${ln}`,
        father: `${ffn} ${ln}`
      });
    }
    return result;
  };

